public class ScoreTablePrinterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + quote(expected) + " but got " + quote(actual));
            failures++;
        }
    }

    static String quote(Object value) {
        if (value == null) {
            return "null";
        }
        return "\"" + value.toString().replace("\n", "\\n") + "\"";
    }

    static String capture(String[] names, int[] scores) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            ScoreTablePrinter.printTable(names, scores);
        } catch (RuntimeException ex) {
            System.setOut(old);
            return "threw " + ex;
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        String header = "NAME         SCORE\n------------------\n";

        String two = capture(new String[] {"alice", "bob"}, new int[] {95, 7});
        check("two rows", header + "alice           95\nbob              7\n", two);

        String one = capture(new String[] {"zed"}, new int[] {100});
        check("one row", header + "zed            100\n", one);

        String empty = capture(new String[] {}, new int[] {});
        check("empty table still prints header and dashes", header, empty);

        String negative = capture(new String[] {"ivy"}, new int[] {-3});
        check("negative score right justified", header + "ivy             -3\n", negative);

        String longName = capture(new String[] {"bartholomew1"}, new int[] {42});
        check("name exactly 12 wide", header + "bartholomew1    42\n", longName);

        String[] lines = two.split("\n", -1);
        check("header line is 18 characters", 18, lines[0].length());
        check("dash line is 18 dashes", "------------------", lines.length > 1 ? lines[1] : "");
        check("row line is 18 characters", 18, lines.length > 2 ? lines[2].length() : -1);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

