public class ScoreTablePrinter {

    public static void printTable(String[] names, int[] scores) {
        System.out.printf("%-12s%6s%n", "NAME", "SCORE");
        for (int i = 0; i < 18; i++) {
            System.out.print("-");
        }
        System.out.println();
        for (int i = 0; i < names.length; i++) {
            System.out.printf("%-12s%6d%n", names[i], scores[i]);
        }
    }
}
